output_text:
[
  {
    "id": "no_cart_two_sided_aisle",
    "text": "Carts are forbidden in the single-file shelf aisles where shelves line both sides of the shopper.",
    "abstraction": {
      "state_properties": {
        "twoSidedShelfAisle": {
          "and": [
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "twoSidedShelfAisle"
        ]
      }
    }
  },
  {
    "id": "enter_pedestrian_aisle_on_foot",
    "text": "A shopper may enter a two-sided single-file shelf aisle only on foot, never while pushing a cart.",
    "abstraction": {
      "state_properties": {
        "twoSidedShelfAisle": {
          "and": [
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "enterTwoSidedShelfAisleWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "twoSidedShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterTwoSidedShelfAisleWithCart"
    }
  },
  {
    "id": "park_cart_only_at_aisle_mouth",
    "text": "Parking or letting go of a cart is allowed only at the wide mouth cells of pedestrian shelf aisles.",
    "abstraction": {
      "state_properties": {
        "cartBay": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "parkCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "parkCart",
          {
            "not": "cartBay"
          }
        ]
      }
    }
  },
  {
    "id": "retrieve_cart_after_pedestrian_trip",
    "text": "After returning on foot to a cart bay, the shopper is obliged to retrieve the parked cart.",
    "abstraction": {
      "state_properties": {
        "cartBay": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "atCartBayOnFoot": {
          "and": [
            "cartBay",
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {
        "retrieveCart": {
          "pre": {
            "and": [
              "atCartBayOnFoot",
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "atCartBayOnFoot",
      "discharge": "retrieveCart"
    }
  },
  {
    "id": "no_cartless_travel_in_open_store",
    "text": "Except at the entrance, in cart bays, or inside pedestrian shelf aisles, moving around the store without a cart is forbidden.",
    "abstraction": {
      "state_properties": {
        "entranceZone": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "cartBay": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "twoSidedShelfAisle": {
          "and": [
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "permittedOnFootZone": {
          "or": [
            "entranceZone",
            "cartBay",
            "twoSidedShelfAisle"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "MOVE",
          {
            "not": "hasCart"
          },
          {
            "not": "permittedOnFootZone"
          }
        ]
      }
    }
  },
  {
    "id": "cart_required_for_open_shelf_service",
    "text": "Shelf interactions in open cart-accessible aisles must be performed while holding a cart.",
    "abstraction": {
      "state_properties": {
        "twoSidedShelfAisle": {
          "and": [
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "openShelfServicePoint": {
          "and": [
            "adjShelf",
            {
              "not": "twoSidedShelfAisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "openShelfServicePoint",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "pedestrian_aisle_entry_requires_pick",
    "text": "Entering a two-sided pedestrian shelf aisle creates an obligation to interact with a shelf in that aisle.",
    "abstraction": {
      "state_properties": {
        "twoSidedShelfAisle": {
          "and": [
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "enterTwoSidedShelfAisleOnFoot": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "MOVE"
            ]
          },
          "post": "twoSidedShelfAisle"
        },
        "interactInTwoSidedShelfAisle": {
          "pre": {
            "and": [
              "twoSidedShelfAisle",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "enterTwoSidedShelfAisleOnFoot",
      "discharge": "interactInTwoSidedShelfAisle"
    }
  },
  {
    "id": "must_take_entrance_cart",
    "text": "At the start of shopping, the shopper is obliged to take a cart from the entrance cart pickup cell.",
    "abstraction": {
      "state_properties": {
        "cartPickupCell": "at(1,7)"
      },
      "events": {
        "takeEntranceCart": {
          "pre": {
            "and": [
              "cartPickupCell",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "takeEntranceCart"
    }
  }
]
